const signalAlertsUrl="function"==typeof window.buildDataUrl?window.buildDataUrl("data/signal_alerts.json"):new URL("data/signal_alerts.json",window.location.href).toString();fetch(signalAlertsUrl).then(n=>{if(404===n.status)return[]; if(!n.ok)throw new Error(`Failed to load signal alerts (${n.status} ${n.statusText})`);return n.json()}).then(n=>{const a=Array.isArray(n)?n:[],t=document.getElementById("signalAlertContainer"),l=document.getElementById("signalAlertCount");l&&(l.textContent=a.length),t&&(a.length?a.forEach(n=>{const a=document.createElement("div");a.className="signal-change-item",a.innerHTML=`\n  <div class="signal-symbol">${n.symbol}</div>\n  <div class="signal-flow">\n    <span class="old-signal">${n.old_signal}</span>\n    <span class="material-icons-outlined">arrow_forward</span>\n    <span class="new-signal">${n.new_signal}</span>\n  </div>\n`,t.appendChild(a)}):t.innerHTML="<div class='signal-empty'>No signal changes detected.</div>")}).catch(n=>{console.error("Error loading signal alerts:",n);const a=document.getElementById("signalAlertContainer");a&&(a.innerHTML="<div class='signal-empty text-warning'>Failed to load signal alert data.</div>")});
